package net.civeira.phylax.features.document.templateversion.application.usecase.list;

import java.util.List;
import java.util.Optional;

import lombok.Builder;
import lombok.Data;
import lombok.EqualsAndHashCode;
import lombok.With;
import net.civeira.phylax.features.document.template.domain.TemplateRef;

@Data
@Builder(toBuilder = true)
@With
@EqualsAndHashCode(onlyExplicitlyIncluded = true)
public class TemplateVersionListFilter {

  /**
   * The filter to select the results to retrieve
   *
   * @autogenerated ListFilterGenerator
   */
  private String search;

  /**
   * @autogenerated ListFilterGenerator
   */
  private TemplateRef template;

  /**
   * @autogenerated ListFilterGenerator
   */
  private String templateTenantAccesible;

  /**
   * @autogenerated ListFilterGenerator
   */
  private List<String> templates;

  /**
   * The filter to select the results to retrieve
   *
   * @autogenerated ListFilterGenerator
   */
  private String uid;

  /**
   * The filter to select the results to retrieve
   *
   * @autogenerated ListFilterGenerator
   */
  private List<String> uids;

  /**
   * @autogenerated ListFilterGenerator
   * @return
   */
  public Optional<String> getSearch() {
    return Optional.ofNullable(search);
  }

  /**
   * @autogenerated ListFilterGenerator
   * @return
   */
  public Optional<TemplateRef> getTemplate() {
    return Optional.ofNullable(template);
  }

  /**
   * @autogenerated ListFilterGenerator
   * @return
   */
  public Optional<String> getTemplateTenantAccesible() {
    return Optional.ofNullable(templateTenantAccesible);
  }

  /**
   * @autogenerated ListFilterGenerator
   * @return
   */
  public List<String> getTemplates() {
    return null == templates ? List.of() : List.copyOf(templates);
  }

  /**
   * @autogenerated ListFilterGenerator
   * @return
   */
  public Optional<String> getUid() {
    return Optional.ofNullable(uid);
  }

  /**
   * @autogenerated ListFilterGenerator
   * @return
   */
  public List<String> getUids() {
    return null == uids ? List.of() : List.copyOf(uids);
  }
}
